-- =========================================================
-- 南湖家园停车高峰分析测试数据
-- 生成范围：2026-04-01 ~ 2026-04-07
-- 每天记录数：120 条，共 840 条
-- 小区：南湖家园 community_id = 1256522511225511225
-- 说明：本脚本只插入 community_parking_record，不修改车辆、车位、业主、房屋等基础表。
-- 使用前建议先备份数据库。
-- =========================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- 避免重复执行导致主键冲突：删除本脚本生成过的数据
DELETE FROM `community_parking_record`
WHERE `community_id` = 1256522511225511225
  AND `in_time` >= '2026-04-01 00:00:00'
  AND `in_time` <  '2026-04-08 00:00:00'
  AND `remark` LIKE '南湖家园停车高峰分析测试数据%';

DELETE FROM `community_parking_record`
WHERE `record_id` BETWEEN 2604010001 AND 2604070120;


COMMIT;

-- =========================================================
-- 验证 SQL：执行插入后可单独运行
-- =========================================================
-- 1. 检查每天是否不少于 100 条
SELECT DATE(`in_time`) AS stat_date, COUNT(*) AS record_count
FROM `community_parking_record`
WHERE `community_id` = 1256522511225511225
  AND `in_time` >= '2026-04-01 00:00:00'
  AND `in_time` <  '2026-04-08 00:00:00'
  AND `remark` LIKE '南湖家园停车高峰分析测试数据%'
GROUP BY DATE(`in_time`)
ORDER BY stat_date;

-- 2. 按入场小时统计，用于快速观察晚高峰入场分布
SELECT DATE(`in_time`) AS stat_date, HOUR(`in_time`) AS in_hour, COUNT(*) AS record_count
FROM `community_parking_record`
WHERE `community_id` = 1256522511225511225
  AND `in_time` >= '2026-04-01 00:00:00'
  AND `in_time` <  '2026-04-08 00:00:00'
  AND `remark` LIKE '南湖家园停车高峰分析测试数据%'
GROUP BY DATE(`in_time`), HOUR(`in_time`)
ORDER BY stat_date, in_hour;

-- 3. 按系统停车高峰口径统计单日每小时在场车辆数，示例：2026-04-07
WITH RECURSIVE hours AS (
    SELECT 0 AS h
    UNION ALL
    SELECT h + 1 FROM hours WHERE h < 23
)
SELECT
    LPAD(h.h, 2, '0') AS hour_start,
    COUNT(pr.record_id) AS active_parking_count
FROM hours h
LEFT JOIN `community_parking_record` pr
  ON pr.community_id = 1256522511225511225
 AND pr.in_time <  TIMESTAMP('2026-04-07 00:00:00') + INTERVAL (h.h + 1) HOUR
 AND (pr.out_time IS NULL OR pr.out_time >= TIMESTAMP('2026-04-07 00:00:00') + INTERVAL h.h HOUR)
 AND pr.remark LIKE '南湖家园停车高峰分析测试数据%'
GROUP BY h.h
ORDER BY h.h;
